package org.updraft.betterstatus.storage;
import org.updraft.betterstatus.model.ServerSnapshot; import java.sql.*; import java.util.*;
public final class HistoryStore implements AutoCloseable {private final Connection c;public HistoryStore(String url)throws SQLException{c=DriverManager.getConnection(url);try(Statement s=c.createStatement()){s.executeUpdate("CREATE TABLE IF NOT EXISTS status_events(id INTEGER PRIMARY KEY AUTOINCREMENT,server TEXT NOT NULL,state TEXT NOT NULL,changed_at INTEGER NOT NULL,ping_ms INTEGER NOT NULL,players INTEGER NOT NULL)");s.executeUpdate("CREATE INDEX IF NOT EXISTS status_events_idx ON status_events(server,changed_at)");}}public synchronized void record(ServerSnapshot x)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO status_events(server,state,changed_at,ping_ms,players) VALUES(?,?,?,?,?)")){p.setString(1,x.name());p.setString(2,x.state().name());p.setLong(3,x.stateChangedMillis());p.setLong(4,x.pingMillis());p.setInt(5,x.players());p.executeUpdate();}}public synchronized List<String> recent(String n,int limit)throws SQLException{List<String> out=new ArrayList<>();try(PreparedStatement p=c.prepareStatement("SELECT state,changed_at,ping_ms,players FROM status_events WHERE server=? ORDER BY changed_at DESC LIMIT ?")){p.setString(1,n);p.setInt(2,Math.max(1,Math.min(limit,100)));try(ResultSet r=p.executeQuery()){while(r.next())out.add(r.getString(1)+" @ "+r.getLong(2)+" ping="+r.getLong(3)+"ms players="+r.getInt(4));}}return out;}public synchronized void close()throws SQLException{c.close();}}